private class BrowserPalette(dark: Boolean) {
  val bg = if (dark) 0xFF1A1A1A.toInt() else 0xFFFFFFFF.toInt()
  val surface = if (dark) 0xFF242424.toInt() else 0xFFF6F8FA.toInt()
  val border = if (dark) 0xFF2D2D2D.toInt() else 0xFFE5E8EC.toInt()
  val borderStrong = if (dark) 0xFF3D3D3D.toInt() else 0xFFD1D9E0.toInt()
  val text = if (dark) 0xFFD6DBE0.toInt() else 0xFF1F2328.toInt()
  val textMuted = if (dark) 0xFF9198A1.toInt() else 0xFF59636E.toInt()
  val disabled = if (dark) 0xFF4E555E.toInt() else 0xFFB0B8C1.toInt()
  val accent = if (dark) 0xFF4493F8.toInt() else 0xFF0969DA.toInt()
  val warn = if (dark) 0xFFD29922.toInt() else 0xFF9A6700.toInt()
  val ripple = if (dark) 0x22FFFFFF else 0x18000000
}

