private enum class BrowserIcon {
  CLOSE,
  MORE,
  BACK,
  FORWARD,
  REFRESH,
  EXTERNAL,
  LOCK,
  HTTP_WARN,
  COPY,
  SHARE,
  DESKTOP,
  CLOUD_OFF,
}

private class StrokeIconDrawable(
  private val icon: BrowserIcon,
  private val sizePx: Int,
  color: Int,
  private val strokePx: Float,
) : Drawable() {
  private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
    style = Paint.Style.STROKE
    strokeCap = Paint.Cap.ROUND
    strokeJoin = Paint.Join.ROUND
    this.color = color
  }
  private val fillPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
    style = Paint.Style.FILL
    this.color = color
  }

  fun setTintColor(color: Int) {
    paint.color = color
    fillPaint.color = color
    invalidateSelf()
  }

  override fun getIntrinsicWidth(): Int = sizePx
  override fun getIntrinsicHeight(): Int = sizePx

  override fun draw(canvas: Canvas) {
    val b = bounds
    val side = minOf(b.width(), b.height()).toFloat()
    if (side <= 0f) return
    val scale = side / 24f
    val ox = b.left + (b.width() - side) / 2f
    val oy = b.top + (b.height() - side) / 2f
    paint.strokeWidth = strokePx / scale

    canvas.save()
    canvas.translate(ox, oy)
    canvas.scale(scale, scale)

    when (icon) {
      BrowserIcon.CLOSE -> {
        canvas.drawLine(6f, 6f, 18f, 18f, paint)
        canvas.drawLine(18f, 6f, 6f, 18f, paint)
      }
      BrowserIcon.MORE -> {
        canvas.drawCircle(5.5f, 12f, 1.35f, fillPaint)
        canvas.drawCircle(12f, 12f, 1.35f, fillPaint)
        canvas.drawCircle(18.5f, 12f, 1.35f, fillPaint)
      }
      BrowserIcon.BACK -> {
        canvas.drawLine(19f, 12f, 5f, 12f, paint)
        val p = Path().apply {
          moveTo(11f, 6f)
          lineTo(5f, 12f)
          lineTo(11f, 18f)
        }
        canvas.drawPath(p, paint)
      }
      BrowserIcon.FORWARD -> {
        canvas.drawLine(5f, 12f, 19f, 12f, paint)
        val p = Path().apply {
          moveTo(13f, 6f)
          lineTo(19f, 12f)
          lineTo(13f, 18f)
        }
        canvas.drawPath(p, paint)
      }
      BrowserIcon.REFRESH -> {
        val oval = RectF(4f, 4f, 20f, 20f)
        canvas.drawArc(oval, -35f, 305f, false, paint)
        val arrow = Path().apply {
          moveTo(20f, 4.5f)
          lineTo(20f, 9.5f)
          lineTo(15f, 9.5f)
        }
        canvas.drawPath(arrow, paint)
      }
      BrowserIcon.EXTERNAL -> {
        val box = Path().apply {
          moveTo(18f, 13f)
          lineTo(18f, 19f)
          lineTo(5f, 19f)
          lineTo(5f, 6f)
          lineTo(11f, 6f)
        }
        canvas.drawPath(box, paint)
        val tip = Path().apply {
          moveTo(15f, 4f)
          lineTo(20f, 4f)
          lineTo(20f, 9f)
        }
        canvas.drawPath(tip, paint)
        canvas.drawLine(10f, 14f, 20f, 4f, paint)
      }
      BrowserIcon.LOCK -> {
        canvas.drawRoundRect(RectF(5f, 11f, 19f, 20f), 2f, 2f, paint)
        val arch = Path().apply {
          moveTo(8f, 11f)
          lineTo(8f, 8f)
          arcTo(RectF(8f, 4f, 16f, 12f), 180f, 180f, false)
          lineTo(16f, 11f)
        }
        canvas.drawPath(arch, paint)
      }
      BrowserIcon.HTTP_WARN -> {
        canvas.drawCircle(12f, 12f, 9f, paint)
        canvas.drawLine(12f, 11f, 12f, 16f, paint)
        canvas.drawCircle(12f, 8f, 1.0f, fillPaint)
      }
      BrowserIcon.COPY -> {
        canvas.drawRoundRect(RectF(8f, 8f, 20f, 20f), 2f, 2f, paint)
        val back = Path().apply {
          moveTo(4f, 16f)
          lineTo(4f, 4f)
          lineTo(16f, 4f)
        }
        canvas.drawPath(back, paint)
      }
      BrowserIcon.SHARE -> {
        canvas.drawCircle(18f, 5.5f, 2.2f, paint)
        canvas.drawCircle(6f, 12f, 2.2f, paint)
        canvas.drawCircle(18f, 18.5f, 2.2f, paint)
        canvas.drawLine(8f, 10.9f, 16f, 6.6f, paint)
        canvas.drawLine(8f, 13.1f, 16f, 17.4f, paint)
      }
      BrowserIcon.DESKTOP -> {
        canvas.drawRoundRect(RectF(3f, 5f, 21f, 16f), 2f, 2f, paint)
        canvas.drawLine(12f, 16f, 12f, 20f, paint)
        canvas.drawLine(8f, 20f, 16f, 20f, paint)
      }
      BrowserIcon.CLOUD_OFF -> {
        val cloud = Path().apply {
          moveTo(7f, 18f)
          lineTo(16.5f, 18f)
          arcTo(RectF(13f, 10f, 21f, 18f), 90f, -155f, false)
          arcTo(RectF(7f, 6f, 17f, 16f), -25f, -135f, false)
          arcTo(RectF(3f, 10f, 11f, 18f), -160f, -110f, false)
          close()
        }
        canvas.drawPath(cloud, paint)
        canvas.drawLine(3.5f, 3.5f, 20.5f, 20.5f, paint)
      }
    }
    canvas.restore()
  }

  override fun setAlpha(alpha: Int) {
    paint.alpha = alpha
    fillPaint.alpha = alpha
  }

  override fun setColorFilter(colorFilter: ColorFilter?) {
    paint.colorFilter = colorFilter
    fillPaint.colorFilter = colorFilter
  }

  @Suppress("DEPRECATION")
  override fun getOpacity(): Int = PixelFormat.TRANSLUCENT
}

private class InAppBrowserDialog(
  private val activity: MainActivity,
  initialUrl: String,
  private val dark: Boolean,
  private val en: Boolean,
  private val onDismissed: (InAppBrowserDialog) -> Unit,
) : ComponentDialog(activity, android.R.style.Theme_NoTitleBar) {

  private val palette = BrowserPalette(dark)
  private val str = BrowserStrings(en)
  private val density = activity.resources.displayMetrics.density

  private var currentUrl = initialUrl
  private var pageTitle = ""
  private var isLoading = false
  private var mainFrameError = false
  private var desktopMode = false
  private var destroyed = false
  private var mobileUa = ""
  private var desktopUa = ""

  private lateinit var root: FrameLayout
  private lateinit var mainCol: LinearLayout
  private lateinit var topBar: LinearLayout
  private lateinit var titleView: TextView
  private lateinit var schemeIcon: ImageView
  private lateinit var schemeDrawable: StrokeIconDrawable
  private lateinit var subtitleView: TextView
  private lateinit var progressBar: ProgressBar
  private lateinit var webWrap: FrameLayout
  private var webView: WebView? = null
  private lateinit var errorOverlay: LinearLayout
  private lateinit var errorDetailView: TextView
  private lateinit var bottomDivider: View
  private lateinit var bottomBar: LinearLayout
  private lateinit var backBtn: ImageButton
  private lateinit var backDrawable: StrokeIconDrawable
  private lateinit var forwardBtn: ImageButton
  private lateinit var forwardDrawable: StrokeIconDrawable
  private lateinit var reloadBtn: ImageButton
  private lateinit var reloadDrawable: StrokeIconDrawable
  private lateinit var externalBtn: ImageButton
  private lateinit var fullscreenContainer: FrameLayout

  private var customView: View? = null
  private var customViewCallback: WebChromeClient.CustomViewCallback? = null
  private var overflowSheet: BottomSheetDialog? = null

  private fun dp(v: Int): Int = (v * density).toInt()
  private fun dpF(v: Float): Float = v * density

  private fun rippleBackground(bgColor: Int = Color.TRANSPARENT, cornerPx: Float = 0f): RippleDrawable {
    val content = if (bgColor != Color.TRANSPARENT || cornerPx > 0f) {
      GradientDrawable().apply {
        setColor(bgColor)
        cornerRadius = cornerPx
      }
    } else null
    val mask = GradientDrawable().apply {
      setColor(Color.WHITE)
      cornerRadius = cornerPx
    }
    return RippleDrawable(ColorStateList.valueOf(palette.ripple), content, mask)
  }

  private fun makeIconButton(
    icon: BrowserIcon,
    desc: String,
    sizeDp: Int = 20,
    strokeDp: Float = 1.85f,
    onClick: () -> Unit,
  ): Pair<ImageButton, StrokeIconDrawable> {
    val d = StrokeIconDrawable(icon, dp(sizeDp), palette.text, dpF(strokeDp))
    val btn = ImageButton(activity).apply {
      setImageDrawable(d)
      scaleType = ImageView.ScaleType.CENTER
      background = rippleBackground(cornerPx = dpF(20f))
      contentDescription = desc
      setOnClickListener { onClick() }
    }
    return Pair(btn, d)
  }

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    window?.let { w ->
      WindowCompat.setDecorFitsSystemWindows(w, false)
      w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
      w.setBackgroundDrawable(ColorDrawable(palette.bg))
      @Suppress("DEPRECATION")
      w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE)
      if (Build.VERSION.SDK_INT >= 28) {
        w.attributes = w.attributes.apply {
          layoutInDisplayCutoutMode = WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES
        }
      }
      WindowInsetsControllerCompat(w, w.decorView).apply {
        isAppearanceLightStatusBars = !dark
        isAppearanceLightNavigationBars = !dark
      }
    }

    buildUi()
    setContentView(root)
    updateUrlUi(currentUrl)
    updateNavButtons()

    onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
      override fun handleOnBackPressed() {
        val wv = webView
        if (customView != null) {
          exitFullscreenVideo()
        } else if (errorOverlay.visibility != View.VISIBLE && wv != null && wv.canGoBack()) {
          wv.goBack()
        } else {
          dismissSafely()
        }
      }
    })

    setOnDismissListener {
      if (!destroyed) cleanup()
    }

    ViewCompat.requestApplyInsets(root)
    webView?.loadUrl(currentUrl)
  }

  private fun buildUi() {
    root = FrameLayout(activity).apply {
      setBackgroundColor(palette.bg)
    }

    mainCol = LinearLayout(activity).apply {
      orientation = LinearLayout.VERTICAL
      layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
    }

    // Top bar (52dp content row + top status bar inset)
    topBar = LinearLayout(activity).apply {
      orientation = LinearLayout.HORIZONTAL
      gravity = Gravity.CENTER_VERTICAL
      setBackgroundColor(palette.bg)
      layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
    }

    val (closeBtn, _) = makeIconButton(BrowserIcon.CLOSE, str.close, sizeDp = 20) { dismissSafely() }
    topBar.addView(closeBtn, LinearLayout.LayoutParams(dp(44), dp(52)))

    val titleCol = LinearLayout(activity).apply {
      orientation = LinearLayout.VERTICAL
      gravity = Gravity.CENTER_VERTICAL
      setPadding(dp(4), 0, dp(4), 0)
      background = rippleBackground(cornerPx = dpF(8f))
      setOnClickListener { copyCurrentUrl() }
    }
    titleView = TextView(activity).apply {
      text = str.loading
      setTextColor(palette.text)
      setTextSize(TypedValue.COMPLEX_UNIT_SP, 14.5f)
      typeface = Typeface.DEFAULT_BOLD
      maxLines = 1
      ellipsize = TextUtils.TruncateAt.END
    }
    titleCol.addView(titleView, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT))

    val subRow = LinearLayout(activity).apply {
      orientation = LinearLayout.HORIZONTAL
      gravity = Gravity.CENTER_VERTICAL
    }
    schemeDrawable = StrokeIconDrawable(BrowserIcon.LOCK, dp(11), palette.textMuted, dpF(1.6f))
    schemeIcon = ImageView(activity).apply {
      setImageDrawable(schemeDrawable)
      scaleType = ImageView.ScaleType.CENTER_INSIDE
    }
    subRow.addView(schemeIcon, LinearLayout.LayoutParams(dp(12), dp(12)).apply { marginEnd = dp(4) })

    subtitleView = TextView(activity).apply {
      setTextColor(palette.textMuted)
      setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f)
      maxLines = 1
      ellipsize = TextUtils.TruncateAt.END
    }
    subRow.addView(subtitleView, LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f))
    titleCol.addView(subRow, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(1) })
    topBar.addView(titleCol, LinearLayout.LayoutParams(0, dp(52), 1f))

    val (moreBtn, _) = makeIconButton(BrowserIcon.MORE, str.more, sizeDp = 20) { showOverflowSheet() }
    topBar.addView(moreBtn, LinearLayout.LayoutParams(dp(44), dp(52)))
    mainCol.addView(topBar)

    // 1dp hairline border with 2dp accent progress bar overlaid cleanly
    val progressWrap = FrameLayout(activity).apply {
      layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(2))
    }
    val topHairline = View(activity).apply {
      setBackgroundColor(palette.border)
      layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, maxOf(1, dp(1)), Gravity.TOP)
    }
    progressBar = ProgressBar(activity, null, android.R.attr.progressBarStyleHorizontal).apply {
      max = 100
      progress = 0
      visibility = View.GONE
      progressDrawable = LayerDrawable(
        arrayOf(
          ColorDrawable(Color.TRANSPARENT),
          ClipDrawable(ColorDrawable(palette.accent), Gravity.START, ClipDrawable.HORIZONTAL),
        )
      )
      layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(2))
    }
    progressWrap.addView(topHairline)
    progressWrap.addView(progressBar)
    mainCol.addView(progressWrap)

    // WebView + Error Overlay container
    webWrap = FrameLayout(activity).apply {
      layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
    }
    errorOverlay = buildErrorOverlay()
    webWrap.addView(errorOverlay)
    createAndAttachWebView()
    mainCol.addView(webWrap)

    // Bottom divider + 44dp navigation bar
    bottomDivider = View(activity).apply {
      setBackgroundColor(palette.border)
      layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, maxOf(1, dp(1)))
    }
    mainCol.addView(bottomDivider)

    bottomBar = LinearLayout(activity).apply {
      orientation = LinearLayout.HORIZONTAL
      gravity = Gravity.CENTER_VERTICAL
      setBackgroundColor(palette.bg)
      layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
    }

    val (bBtn, bIcon) = makeIconButton(BrowserIcon.BACK, str.back, sizeDp = 20) {
      val wv = webView ?: return@makeIconButton
      if (wv.canGoBack()) {
        mainFrameError = false
        errorOverlay.visibility = View.GONE
        wv.goBack()
      }
    }
    backBtn = bBtn
    backDrawable = bIcon

    val (fBtn, fIcon) = makeIconButton(BrowserIcon.FORWARD, str.forward, sizeDp = 20) {
      val wv = webView ?: return@makeIconButton
      if (wv.canGoForward()) {
        mainFrameError = false
        errorOverlay.visibility = View.GONE
        wv.goForward()
      }
    }
    forwardBtn = fBtn
    forwardDrawable = fIcon

    val (rBtn, rIcon) = makeIconButton(BrowserIcon.REFRESH, str.reload, sizeDp = 19) {
      if (isLoading) webView?.stopLoading() else reloadPage()
    }
    reloadBtn = rBtn
    reloadDrawable = rIcon

    val (eBtn, _) = makeIconButton(BrowserIcon.EXTERNAL, str.openExternal, sizeDp = 19) {
      activity.openInExternalBrowser(currentUrl, en)
    }
    externalBtn = eBtn

    for (btn in listOf(backBtn, forwardBtn, reloadBtn, externalBtn)) {
      bottomBar.addView(btn, LinearLayout.LayoutParams(0, dp(44), 1f))
    }
    mainCol.addView(bottomBar)
    root.addView(mainCol)

    fullscreenContainer = FrameLayout(activity).apply {
      setBackgroundColor(Color.BLACK)
      visibility = View.GONE
      layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
    }
    root.addView(fullscreenContainer)

    ViewCompat.setOnApplyWindowInsetsListener(root) { _, insets ->
      val topInset = insets.getInsets(WindowInsetsCompat.Type.statusBars() or WindowInsetsCompat.Type.displayCutout()).top
      val navBottom = insets.getInsets(WindowInsetsCompat.Type.navigationBars()).bottom
      val imeBottom = insets.getInsets(WindowInsetsCompat.Type.ime()).bottom
      val sideInsets = insets.getInsets(WindowInsetsCompat.Type.systemBars() or WindowInsetsCompat.Type.displayCutout())
      topBar.setPadding(sideInsets.left + dp(6), topInset, sideInsets.right + dp(6), 0)
      if (imeBottom > 0) {
        bottomDivider.visibility = View.GONE
        bottomBar.visibility = View.GONE
        mainCol.setPadding(0, 0, 0, imeBottom)
      } else {
        bottomDivider.visibility = View.VISIBLE
        bottomBar.visibility = View.VISIBLE
        mainCol.setPadding(0, 0, 0, 0)
        bottomBar.setPadding(sideInsets.left + dp(8), 0, sideInsets.right + dp(8), navBottom)
      }
      fullscreenContainer.setPadding(sideInsets.left, topInset, sideInsets.right, navBottom)
      insets
    }
  }

  private fun buildErrorOverlay(): LinearLayout {
    val wrap = LinearLayout(activity).apply {
      orientation = LinearLayout.VERTICAL
      gravity = Gravity.CENTER
      setBackgroundColor(palette.bg)
      setPadding(dp(28), dp(28), dp(28), dp(28))
      visibility = View.GONE
      isClickable = true
      layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
    }

    val badge = FrameLayout(activity).apply {
      background = GradientDrawable().apply {
        shape = GradientDrawable.OVAL
        setColor(palette.surface)
      }
    }
    val errIcon = ImageView(activity).apply {
      setImageDrawable(StrokeIconDrawable(BrowserIcon.CLOUD_OFF, dp(34), palette.textMuted, dpF(1.75f)))
      scaleType = ImageView.ScaleType.CENTER
    }
    badge.addView(errIcon, FrameLayout.LayoutParams(dp(72), dp(72), Gravity.CENTER))
    wrap.addView(badge, LinearLayout.LayoutParams(dp(72), dp(72)).apply { bottomMargin = dp(18) })

    val heading = TextView(activity).apply {
      text = str.errorTitle
      setTextColor(palette.text)
      setTextSize(TypedValue.COMPLEX_UNIT_SP, 17f)
      typeface = Typeface.DEFAULT_BOLD
      gravity = Gravity.CENTER
    }
    wrap.addView(heading, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) })

    errorDetailView = TextView(activity).apply {
      setTextColor(palette.textMuted)
      setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)
      gravity = Gravity.CENTER
      maxLines = 4
      ellipsize = TextUtils.TruncateAt.END
    }
    wrap.addView(errorDetailView, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(22) })

    val btnRow = LinearLayout(activity).apply {
      orientation = LinearLayout.HORIZONTAL
      gravity = Gravity.CENTER
    }

    val retryBtn = TextView(activity).apply {
      text = str.retry
      setTextColor(Color.WHITE)
      setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)
      typeface = Typeface.DEFAULT_BOLD
      gravity = Gravity.CENTER
      setPadding(dp(20), dp(10), dp(20), dp(10))
      background = rippleBackground(bgColor = palette.accent, cornerPx = dpF(20f))
      setOnClickListener { reloadPage() }
    }
    btnRow.addView(retryBtn, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { marginEnd = dp(10) })

    val extBtn = TextView(activity).apply {
      text = str.openExternal
      setTextColor(palette.text)
      setTextSize(TypedValue.COMPLEX_UNIT_SP, 13.5f)
      gravity = Gravity.CENTER
      setPadding(dp(16), dp(10), dp(16), dp(10))
      val strokeBg = GradientDrawable().apply {
        setColor(palette.surface)
        setStroke(maxOf(1, dp(1)), palette.borderStrong)
        cornerRadius = dpF(20f)
      }
      val mask = GradientDrawable().apply {
        setColor(Color.WHITE)
        cornerRadius = dpF(20f)
      }
      background = RippleDrawable(ColorStateList.valueOf(palette.ripple), strokeBg, mask)
      setOnClickListener { activity.openInExternalBrowser(currentUrl, en) }
    }
    btnRow.addView(extBtn, LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT))
